import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"整数溢出漏洞","description":"","frontmatter":{"title":"整数溢出漏洞","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/integer-overflow-bugs.md","filePath":"cs/integer-overflow-bugs.md","lastUpdated":1789023840000}'),p={name:"cs/integer-overflow-bugs.md"};function u(E,a,_,m,f,A){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="整数溢出漏洞" tabindex="-1">整数溢出漏洞 <a class="header-anchor" href="#整数溢出漏洞" aria-label="Permalink to &quot;整数溢出漏洞&quot;">​</a></h1><div class="epigraph"><p>长度先用机器整数算，再拿去 `malloc` 和 `memcpy`。绕回零的乘会分到短缓冲再写长数据。这是类型与宽度问题，不是「再加一个 canary」能定义的。</p><footer>—— 据 Brumley, Chiueh 等对整数错误的讨论；CWE-190；对照 ISO C 对无符号绕回</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/heap-allocator-attacks">分配器</a>假定请求的大小是诚实的。缺口是<strong>算术</strong>：宽类型截断、有符号转无符号、乘法溢出。本课讲检查应在算术层，不给绕过补丁的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>n * size</code> 绕回后分配很小，循环仍按 <code>n</code> 写。缺口是：所有「计数→字节」的边都要饱和或显式检查。语言若提供检查乘法，应默认用。</p><h3 id="有符号与无符号" tabindex="-1">有符号与无符号 <a class="header-anchor" href="#有符号与无符号" aria-label="Permalink to &quot;有符号与无符号&quot;">​</a></h3><p>比较两边类型不同会让「负长度」变成巨大无符号，另一类洞。</p><p><span class="marginnote">CWE-190/191。本课不写触发某 CVE 的输入。编译器未定义行为对有符号溢出另有坑，点名<a href="/cs/undefined-behavior-opt">未定义行为</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出转换点：乘法、加法、截断、符号。要求 API 用更大类型或饱和。对照：格式化字符串下一课是另一类「解释用户串当格式」。</p>',12)),(e(),n(h,null,{default:r(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MUL%5B%22n%20%C3%97%20size%20%E7%BB%95%E5%9B%9E%22%5D%20--%3E%20SMALL%5B%22%E7%9F%AD%E5%88%86%E9%85%8D%22%5D%0A%20%20SMALL%20--%3E%20COPY%5B%22%E4%BB%8D%E6%8C%89%20n%20%E5%86%99%22%5D%0A%20%20CHK%5B%22%E6%A3%80%E6%9F%A5%E6%88%96%E9%A5%B1%E5%92%8C%22%5D%20--%3E%20OK%5B%22%E6%8B%92%E7%BB%9D%E6%88%96%E6%AD%A3%E7%A1%AE%E5%A4%A7%E5%B0%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>空间安全的输入是长度。长度不可信则分配器与复制都不可信。下一课格式化字符串：控制解释器而不是长度。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给整数溢出 exploit。格式化字符串下一课同样只讲机制与禁用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分配器收到的 size 可能已被绕回。</li><li>计数到字节必须检查宽度。</li><li>符号转换是同类洞。</li><li>下一课格式化字符串。</li><li>出处：CWE-190；ISO C；Brumley et al. 对整数错误的分析。</li></ul>',8))])}const C=l(p,[["render",u]]);export{B as __pageData,C as default};
